"""Use a lexical Bayes router to focus the final answer prompt."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using the ranked label candidates as a guide.

{router_section}

**Problem:**
{input}

The ranking is a word-frequency estimate learned from labeled examples. Check
it against the full meaning of the problem and the task instructions. It is
guidance, not a constraint. Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""

SMOOTHING = 0.1
MAX_CANDIDATES = 5
MAX_QUERY_CUES = 3


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z]{2,}", text.lower())


class BayesianLabelRouter(MemorySystem):
    """Rank learned labels with a smoothed multinomial Bayes evidence model."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.class_token_counts: dict[str, Counter[str]] = {}
        self.class_docs: Counter[str] = Counter()
        self.global_token_counts: Counter[str] = Counter()

    def _rank(self, query: str) -> list[tuple[str, float, list[str]]]:
        labels = sorted(self.class_token_counts, key=str.casefold)
        if not labels:
            return []

        vocabulary_size = max(1, len(self.global_token_counts))
        query_counts = Counter(_tokens(query))
        scores: dict[str, float] = {}
        token_logs: dict[str, dict[str, float]] = {}
        total_docs = max(1, sum(self.class_docs.values()))

        for label in labels:
            counts = self.class_token_counts[label]
            token_total = sum(counts.values())
            denominator = token_total + SMOOTHING * vocabulary_size
            score = math.log((self.class_docs[label] + 1) / (total_docs + len(labels)))
            token_logs[label] = {}
            for token, query_count in query_counts.items():
                if token not in self.global_token_counts:
                    continue
                log_probability = math.log(
                    (counts[token] + SMOOTHING) / denominator
                )
                score += query_count * log_probability
                token_logs[label][token] = log_probability
            scores[label] = score

        ranked_labels = sorted(labels, key=lambda label: scores[label], reverse=True)
        ranked = []
        for label in ranked_labels:
            rivals = [other for other in labels if other != label]
            cues = []
            if rivals:
                differences = []
                for token, value in token_logs[label].items():
                    rival_value = max(
                        (token_logs[other].get(token, 0.0) for other in rivals),
                        default=0.0,
                    )
                    difference = value - rival_value
                    if difference > 0:
                        differences.append((difference, token))
                cues = [token for _, token in sorted(differences, reverse=True)[:MAX_QUERY_CUES]]
            ranked.append((label, scores[label], cues))
        return ranked

    def _format_router(self, query: str) -> str:
        ranked = self._rank(query)
        if not ranked:
            return "No labeled category evidence has been learned yet."

        lines = ["Provisional label ranking (strongest first):"]
        for index, (label, _, cues) in enumerate(ranked[:MAX_CANDIDATES], start=1):
            cue_text = ", ".join(cues) if cues else "no distinct matching word"
            lines.append(
                f"{index}. {label} | training cases: {self.class_docs[label]} | "
                f"matching terms: {cue_text}"
            )
        return "\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        router_section = self._format_router(input)
        response = self.call_llm(PROMPT_TEMPLATE.format(router_section=router_section, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_labels": len(self.class_token_counts),
            "num_candidates": min(len(self.class_token_counts), MAX_CANDIDATES),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            label = str(result["ground_truth"])
            text = str(result.get("raw_question") or result["input"])
            counts = Counter(_tokens(text))
            self.class_token_counts.setdefault(label, Counter()).update(counts)
            self.class_docs[label] += 1
            self.global_token_counts.update(counts)

    def get_context_length(self) -> int:
        return len(self._format_router(""))

    def get_state(self) -> str:
        return json.dumps(
            {
                "class_token_counts": {
                    label: dict(counts)
                    for label, counts in self.class_token_counts.items()
                },
                "class_docs": dict(self.class_docs),
                "global_token_counts": dict(self.global_token_counts),
            },
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.class_token_counts = {
            label: Counter(counts)
            for label, counts in data.get("class_token_counts", {}).items()
        }
        self.class_docs = Counter(data.get("class_docs", {}))
        self.global_token_counts = Counter(data.get("global_token_counts", {}))
"""Retrieve hard, cross-label example pairs near the current problem."""

import json
import math
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem by checking it against these boundary pairs.

{pairs_section}

**Problem:**
{input}

Each pair contains similar earlier problems with different correct outputs.
Identify the detail that separates the two cases, then compare the complete
problem before choosing an answer. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_BOUNDARY_PAIRS = 24
MAX_CONTEXT_PAIRS = 4


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"[a-z]{2,}", text.lower()))


def _overlap(left: set[str], right: set[str]) -> float:
    denominator = min(len(left), len(right))
    return len(left & right) / denominator if denominator else 0.0


class BoundaryPairMemory(MemorySystem):
    """Build a compact bank of similar examples carrying different labels."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.boundary_pairs: dict[str, dict[str, Any]] = {}

    @staticmethod
    def _pair_key(left: str, right: str) -> str:
        return json.dumps(sorted((left, right)), ensure_ascii=False)

    def _add_example(self, example: dict[str, str]) -> None:
        current_tokens = _tokens(example["input"])
        for prior in self.examples:
            if prior["target"] == example["target"]:
                continue
            similarity = _overlap(current_tokens, _tokens(prior["input"]))
            key = self._pair_key(prior["target"], example["target"])
            existing = self.boundary_pairs.get(key)
            if existing is None or similarity > existing["similarity"]:
                self.boundary_pairs[key] = {
                    "left": prior,
                    "right": example,
                    "similarity": similarity,
                }
        self.examples.append(example)

    def _idf(self) -> dict[str, float]:
        document_frequency: dict[str, int] = {}
        for example in self.examples:
            for token in _tokens(example["input"]):
                document_frequency[token] = document_frequency.get(token, 0) + 1
        total = max(1, len(self.examples))
        return {
            token: math.log((total + 1) / (frequency + 1)) + 1
            for token, frequency in document_frequency.items()
        }

    @staticmethod
    def _vector(text: str, idf: dict[str, float]) -> dict[str, float]:
        counts: dict[str, int] = {}
        for token in re.findall(r"[a-z]{2,}", text.lower()):
            counts[token] = counts.get(token, 0) + 1
        vector = {token: count * idf.get(token, 1.0) for token, count in counts.items()}
        norm = math.sqrt(sum(value * value for value in vector.values()))
        return {token: value / norm for token, value in vector.items()} if norm else {}

    @staticmethod
    def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
        return sum(value * right.get(token, 0.0) for token, value in left.items())

    def _select_pairs(self, query: str) -> list[dict[str, Any]]:
        if not self.boundary_pairs:
            return []

        idf = self._idf()
        query_vector = self._vector(query, idf)
        candidates = sorted(
            self.boundary_pairs.values(),
            key=lambda pair: pair["similarity"],
            reverse=True,
        )[:MAX_BOUNDARY_PAIRS]
        if not query:
            return candidates[:MAX_CONTEXT_PAIRS]
        ranked = []
        for pair in candidates:
            left, right = pair["left"], pair["right"]
            left_score = self._cosine(query_vector, self._vector(left["input"], idf))
            right_score = self._cosine(query_vector, self._vector(right["input"], idf))
            ranked.append((max(left_score, right_score), pair))
        ranked.sort(key=lambda item: item[0], reverse=True)
        return [pair for score, pair in ranked[:MAX_CONTEXT_PAIRS] if score > 0]

    def _format_pairs(self, query: str) -> str:
        selected = self._select_pairs(query)
        if not selected:
            return "No learned boundary pairs are available for this problem."

        lines = ["Similar problems with contrasting labels:"]
        for index, pair in enumerate(selected, start=1):
            left, right = pair["left"], pair["right"]
            lines.append(
                f"Pair {index}:\n"
                f"- Problem: {left['input']}\n  Correct output: {left['target']}\n"
                f"- Problem: {right['input']}\n  Correct output: {right['target']}"
            )
        return "\n\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        pairs_section = self._format_pairs(input)
        response = self.call_llm(PROMPT_TEMPLATE.format(pairs_section=pairs_section, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_boundary_pairs": len(self.boundary_pairs),
            "num_retrieved_pairs": len(self._select_pairs(input)),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self._add_example(
                {
                    "input": str(result.get("raw_question") or result["input"]),
                    "target": str(result["ground_truth"]),
                }
            )
        if len(self.boundary_pairs) > MAX_BOUNDARY_PAIRS:
            kept = sorted(
                self.boundary_pairs.items(),
                key=lambda item: item[1]["similarity"],
                reverse=True,
            )[:MAX_BOUNDARY_PAIRS]
            self.boundary_pairs = dict(kept)

    def get_context_length(self) -> int:
        return len(self._format_pairs(""))

    def get_state(self) -> str:
        return json.dumps(
            {
                "examples": self.examples,
                "boundary_pairs": list(self.boundary_pairs.values()),
            },
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
        pairs = data.get("boundary_pairs")
        if pairs is None:
            self.boundary_pairs = {}
            examples = self.examples
            self.examples = []
            for example in examples:
                self._add_example(example)
        else:
            self.boundary_pairs = {
                self._pair_key(pair["left"]["target"], pair["right"]["target"]): pair
                for pair in pairs
            }
"""Retrieve query-relevant labeled examples with multilingual character BM25."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using the most relevant labeled precedents below.

{examples_section}

**Problem:**
{input}

Compare the complete facts with the precedents. Shared wording can suggest a
similarity, but use the full problem to choose the best supported output.
Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

TOP_K = 5
BM25_K1 = 1.2
BM25_B = 0.75
_WORD_RE = re.compile(r"[^\W_]+", flags=re.UNICODE)


def _char_ngrams(text: str) -> Counter[str]:
    features: Counter[str] = Counter()
    for chunk in _WORD_RE.findall(text.lower()):
        for size in (2, 3, 4):
            if len(chunk) >= size:
                features.update(
                    chunk[index : index + size]
                    for index in range(len(chunk) - size + 1)
                )
    return features


class CharNgramCaseRetrieval(MemorySystem):
    """Rank stored examples with BM25 over character n-grams."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    def _rank_examples(self, query: str) -> list[tuple[float, int]]:
        if not self.examples:
            return []
        documents = [_char_ngrams(self._text(example)) for example in self.examples]
        query_terms = _char_ngrams(query)
        if not query_terms:
            start = max(0, len(self.examples) - TOP_K)
            return [(0.0, index) for index in range(start, len(self.examples))]

        document_frequency: Counter[str] = Counter()
        lengths = []
        for document in documents:
            document_frequency.update(document.keys())
            lengths.append(sum(document.values()))
        average_length = sum(lengths) / max(1, len(lengths)) or 1.0
        total = len(documents)

        ranked = []
        for index, document in enumerate(documents):
            length = lengths[index]
            score = 0.0
            for term, query_frequency in query_terms.items():
                frequency = document.get(term, 0)
                if not frequency:
                    continue
                df = document_frequency[term]
                inverse_frequency = math.log(
                    1.0 + (total - df + 0.5) / (df + 0.5)
                )
                denominator = frequency + BM25_K1 * (
                    1.0 - BM25_B + BM25_B * length / average_length
                )
                score += (
                    inverse_frequency
                    * query_frequency
                    * frequency
                    * (BM25_K1 + 1.0)
                    / denominator
                )
            ranked.append((score, index))
        ranked.sort(reverse=True)
        return ranked[:TOP_K]

    def _format_examples(self, query: str) -> str:
        selected = self._rank_examples(query)
        if not selected:
            return "No labeled precedents have been learned yet."
        rows = []
        for rank, (_, index) in enumerate(selected, start=1):
            example = self.examples[index]
            rows.append(
                f"Precedent {rank}:\n"
                f"Problem: {self._text(example)}\n"
                f"Correct output: {example['target']}"
            )
        return "Most textually relevant labeled precedents:\n\n" + "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._rank_examples(input)
        examples_section = self._format_examples(input)
        response = self.call_llm(
            PROMPT_TEMPLATE.format(examples_section=examples_section, input=input)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_examples": len(selected),
            "top_bm25_score": selected[0][0] if selected else 0.0,
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {
                "input": str(result["input"]),
                "target": str(result["ground_truth"]),
            }
            if "raw_question" in result:
                example["raw_question"] = str(result["raw_question"])
            self.examples.append(example)

    def get_context_length(self) -> int:
        return len(self._format_examples(""))

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
