                    "prediction": str(result["prediction"]),
                    "target": str(result["ground_truth"]),
                }
            )
        self.errors = self.errors[-MAX_STORED_ERRORS:]

    def get_state(self) -> str:
        return json.dumps({"errors": self.errors}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.errors = data.get("errors", [])

"""Retrieve labeled cases by blending query similarity with graph walks."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using these directly relevant and graph-related cases.

{examples_section}

**Problem:**
{input}

Nearby cases can connect to other useful precedents through shared details.
Use those connections to find a pattern, then verify it against the complete
problem before answering. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

TOP_K = 5
GRAPH_NEIGHBORS = 6
WALK_STEPS = 5
RESTART_PROBABILITY = 0.30
DIRECT_WEIGHT = 0.90
_WORD_RE = re.compile(r"[^\W_]+", flags=re.UNICODE)


def _char_ngrams(text: str) -> Counter[str]:
    features: Counter[str] = Counter()
    for chunk in _WORD_RE.findall(text.lower()):
        for size in (2, 3):
            if len(chunk) >= size:
                features.update(
                    chunk[index : index + size]
                    for index in range(len(chunk) - size + 1)
                )
    return features


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(feature, 0.0) for feature, value in left.items())


class GraphWalkMemory(MemorySystem):
    """Use a case-neighbor graph to propagate query relevance between examples."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    def _rank_examples(self, query: str) -> list[tuple[float, int, float]]:
        count = len(self.examples)
        if not count:
            return []

        document_features = [_char_ngrams(self._text(example)) for example in self.examples]
        query_features = _char_ngrams(query)
        document_frequency: Counter[str] = Counter()
        for features in document_features:
            document_frequency.update(features.keys())
        vectors = []
        for features in document_features:
            weighted = {
                feature: frequency
                * (math.log((count + 1) / (document_frequency[feature] + 1)) + 1.0)
                for feature, frequency in features.items()
            }
            norm = math.sqrt(sum(value * value for value in weighted.values())) or 1.0
            vectors.append({feature: value / norm for feature, value in weighted.items()})
        weighted_query = {
            feature: frequency
            * (math.log((count + 1) / (document_frequency[feature] + 1)) + 1.0)
            for feature, frequency in query_features.items()
        }
        query_norm = math.sqrt(sum(value * value for value in weighted_query.values())) or 1.0
        query_vector = {feature: value / query_norm for feature, value in weighted_query.items()}

        direct = [_cosine(query_vector, vector) for vector in vectors]
        direct_total = sum(max(0.0, score) for score in direct) or 1.0
        seed = [max(0.0, score) / direct_total for score in direct]

        similarities = [
            [_cosine(vectors[index], vectors[other]) if index != other else 0.0
             for other in range(count)]
            for index in range(count)
        ]
        transitions: list[list[tuple[int, float]]] = []
        for index, row in enumerate(similarities):
            neighbors = sorted(
                (other for other in range(count) if other != index),
                key=lambda other: row[other],
                reverse=True,
            )[:GRAPH_NEIGHBORS]
            total_weight = sum(max(0.0, row[other]) for other in neighbors) or 1.0
            transitions.append(
                [
                    (other, max(0.0, row[other]) / total_weight)
                    for other in neighbors
                    if row[other] > 0
                ]
            )

        walk = seed[:]
        for _ in range(WALK_STEPS):
            updated = [RESTART_PROBABILITY * seed[index] for index in range(count)]
            for source, edges in enumerate(transitions):
                for destination, probability in edges:
                    updated[destination] += (
                        (1.0 - RESTART_PROBABILITY) * walk[source] * probability
                    )
            walk = updated

        ranked = [
            (
                DIRECT_WEIGHT * seed[index] + (1.0 - DIRECT_WEIGHT) * walk[index],
                index,
                walk[index],
            )
            for index in range(count)
        ]
        ranked.sort(reverse=True)
        return ranked[:TOP_K]

    def _format_examples(self, query: str) -> str:
        selected = self._rank_examples(query)
        if not selected:
            return "No labeled cases have been learned yet."
        rows = []
        for rank, (_, index, walk_score) in enumerate(selected, start=1):
            example = self.examples[index]
            rows.append(
                f"Case {rank} (graph support {walk_score:.3f}):\n"
                f"Problem: {self._text(example)}\n"
                f"Correct output: {example['target']}"
            )
        return "Query-connected cases:\n\n" + "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._rank_examples(input)
        response = self.call_llm(
            PROMPT_TEMPLATE.format(
                examples_section=self._format_examples(input), input=input
            )
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_examples": len(selected),
            "mean_graph_support": (
                sum(item[2] for item in selected) / len(selected) if selected else 0.0
            ),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {
                "input": str(result["input"]),
                "target": str(result["ground_truth"]),
            }
            if "raw_question" in result:
                example["raw_question"] = str(result["raw_question"])
            self.examples.append(example)

    def get_context_length(self) -> int:
        return len(self._format_examples(""))

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
"""Consolidate labeled feedback into periodic LLM-authored lessons."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


LESSON_WINDOW = 8
RECENT_CASES = 4
MAX_LESSONS = 16

LEARNING_PROMPT = """Review these problem, attempt, and correct-output records.

Find one concise lesson that could transfer to future problems. Give priority
to distinctions shown by incorrect attempts. Avoid memorizing individual
answers or asserting a rule that the records do not support. Return JSON:
{{"lesson": "[one concise transferable lesson]"}}

Records:
{records}
"""

PREDICT_PROMPT = """Solve the problem using relevant learned lessons and recent examples.

{memory_section}

**Problem:**
{input}

Lessons summarize patterns from earlier feedback. Check that each applies to
this problem before using it. Treat individual examples as evidence, not rules.
Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""


class LessonWindowMemory(MemorySystem):
    """Replace completed feedback windows with short learned lessons."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.lessons: list[str] = []
        self.pending: list[dict[str, Any]] = []
        self.recent: list[dict[str, str]] = []

    def _distill(self, records: list[dict[str, Any]]) -> str:
        prompt = LEARNING_PROMPT.format(
            records=json.dumps(records, ensure_ascii=False, indent=2)
        )
        response = self.call_llm(prompt)
        lesson = extract_json_field(response, "lesson").strip()
        if not lesson:
            lesson = response.strip()
        return lesson[:1000]

    def _format_memory(self) -> str:
        sections = []
        if self.lessons:
            sections.append(
                "Lessons learned from earlier feedback:\n"
                + "\n".join(f"- {lesson}" for lesson in self.lessons)
            )

        unfinished = self.pending[:-RECENT_CASES] if len(self.pending) > RECENT_CASES else []
        cases = [
            {"input": item["input"], "target": item["ground_truth"]}
            for item in unfinished
        ]
        cases.extend(self.recent[-RECENT_CASES:])
        if cases:
            lines = ["Recent or not-yet-consolidated examples:"]
            for case in cases:
                lines.append(f"- Input: {case['input']}\n  Correct output: {case['target']}")
            sections.append("\n".join(lines))

        return "\n\n".join(sections) if sections else "No feedback has been learned yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        memory_section = self._format_memory()
        prompt = PREDICT_PROMPT.format(memory_section=memory_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_lessons": len(self.lessons),
            "num_pending": len(self.pending),
            "num_recent_cases": min(len(self.recent), RECENT_CASES),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            item = {
                "input": str(result.get("raw_question") or result["input"]),
                "prediction": str(result["prediction"]),
                "ground_truth": str(result["ground_truth"]),
                "was_correct": bool(result["was_correct"]),
            }
            self.pending.append(item)
            self.recent.append({"input": item["input"], "target": item["ground_truth"]})
            self.recent = self.recent[-RECENT_CASES:]

            while len(self.pending) >= LESSON_WINDOW:
                window = self.pending[:LESSON_WINDOW]
                lesson = self._distill(window)
                if lesson:
                    self.lessons.append(lesson)
                    self.lessons = self.lessons[-MAX_LESSONS:]
                self.pending = self.pending[LESSON_WINDOW:]

    def get_context_length(self) -> int:
        return len(self._format_memory())

    def get_state(self) -> str:
        return json.dumps(
            {"lessons": self.lessons, "pending": self.pending, "recent": self.recent},
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.lessons = data.get("lessons", [])
        self.pending = data.get("pending", [])
        self.recent = data.get("recent", [])

"""Present query-matched, label-pair contrast cards learned from examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using these learned contrasts between labels.

{contrast_section}

**Problem:**
{input}

The contrast cards summarize words that distinguished the labeled examples in
each pair. Treat them as weak clues, compare the full problem, and select the
best-supported answer. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CARDS = 8
MAX_CUES_PER_SIDE = 3


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"[a-z]{2,}", text.lower()))


class PairwiseContrastMemory(MemorySystem):
    """Learn discriminative terms for pairs of competing labels."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.class_token_docs: dict[str, Counter[str]] = {}
        self.class_docs: Counter[str] = Counter()

    def _cues(
        self, own: Counter[str], other: Counter[str], own_docs: int, other_docs: int
    ) -> list[str]:
        ranked = []
        for token, own_count in own.items():
            # Smoothed log-odds on document presence favors terms that separate
            # the two labels instead of terms that are frequent everywhere.
            other_count = other[token]
            score = math.log((own_count + 0.5) / (own_docs - own_count + 0.5))
            score -= math.log(
                (other_count + 0.5) / (other_docs - other_count + 0.5)
            )
            if score > 0:
                ranked.append((score, token))
        return [token for _, token in sorted(ranked, reverse=True)[:MAX_CUES_PER_SIDE]]

    def _cards(self) -> list[dict[str, Any]]:
        labels = sorted(self.class_token_docs, key=str.casefold)
        cards = []
        for index, left in enumerate(labels):
            for right in labels[index + 1 :]:
                cards.append(
                    {
                        "left": left,
                        "right": right,
                        "left_cues": self._cues(
                            self.class_token_docs[left],
                            self.class_token_docs[right],
                            self.class_docs[left],
                            self.class_docs[right],
                        ),
                        "right_cues": self._cues(
                            self.class_token_docs[right],
                            self.class_token_docs[left],
                            self.class_docs[right],
                            self.class_docs[left],
                        ),
                    }
                )
        return cards

    def _format_contrasts(self, query: str) -> str:
        query_tokens = _tokens(query)
        ranked = []
        for card in self._cards():
            left_hits = query_tokens.intersection(card["left_cues"])
            right_hits = query_tokens.intersection(card["right_cues"])
            hits = len(left_hits) + len(right_hits)
            if hits or not query:
                ranked.append((hits, max(len(left_hits), len(right_hits)), card))

        ranked.sort(
            key=lambda item: (
                item[0],
                item[1],
                len(item[2]["left_cues"]) + len(item[2]["right_cues"]),
            ),
            reverse=True,
        )
        if not ranked:
            return "No learned contrast cues match this problem."

        lines = ["Query-matched label contrasts (left-side cues / right-side cues):"]
        for _, _, card in ranked[:MAX_CARDS]:
            left = ", ".join(card["left_cues"]) or "no cue"
            right = ", ".join(card["right_cues"]) or "no cue"
            lines.append(f"- {card['left']} versus {card['right']}: {left} / {right}")
        return "\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        contrast_section = self._format_contrasts(input)
        prompt = PROMPT_TEMPLATE.format(contrast_section=contrast_section, input=input)
        response = self.call_llm(prompt)
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_label_pairs": len(self._cards()),
            "contrast_chars": len(contrast_section),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            label = str(result["ground_truth"])
            text = str(result.get("raw_question") or result["input"])
            self.class_docs[label] += 1
            self.class_token_docs.setdefault(label, Counter()).update(_tokens(text))

    def get_context_length(self) -> int:
        return len(self._format_contrasts(""))

    def get_state(self) -> str:
        return json.dumps(
            {
                "class_token_docs": {
                    label: dict(counts)
                    for label, counts in self.class_token_docs.items()
                },
                "class_docs": dict(self.class_docs),
            },
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.class_token_docs = {
            label: Counter(counts)
            for label, counts in data.get("class_token_docs", {}).items()
        }
        self.class_docs = Counter(data.get("class_docs", {}))
"""Store extractive, salience-ranked sentence summaries for labeled examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using these concise labeled case extracts.

{examples_section}

**Problem:**
{input}

The extracts retain selected sentences from earlier examples. They are partial
evidence, so compare all available details in the new problem before answering.
Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

SENTENCES_PER_CASE = 4
_WORD_RE = re.compile(r"[^\W_]+", flags=re.UNICODE)
_SENTENCE_BOUNDARY = re.compile(r"(?<=[。！？!?；;.!?])|[\r\n]+")


def _char_ngrams(text: str) -> set[str]:
    features: set[str] = set()
    for chunk in _WORD_RE.findall(text.lower()):
        for size in (2, 3):
            if len(chunk) >= size:
                features.update(
                    chunk[index : index + size]
                    for index in range(len(chunk) - size + 1)
                )
    return features


def _sentences(text: str) -> list[str]:
    parts = [part.strip() for part in _SENTENCE_BOUNDARY.split(text) if part.strip()]
    return parts or ([text.strip()] if text.strip() else [])


class SalientSentenceMemory(MemorySystem):
    """Keep high-information sentence extracts instead of full case text."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.summaries: list[str] = []

    @staticmethod
    def _text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    def _refresh_summaries(self) -> None:
        sentence_groups = [_sentences(self._text(example)) for example in self.examples]
        sentence_features = [
            [_char_ngrams(sentence) for sentence in group]
            for group in sentence_groups
        ]
        document_frequency: Counter[str] = Counter()
        sentence_count = 0
        for group in sentence_features:
            for features in group:
                document_frequency.update(features)
                sentence_count += 1
        total_sentences = max(1, sentence_count)

        summaries = []
        for sentences, feature_group in zip(sentence_groups, sentence_features):
            scored = []
            for index, (sentence, features) in enumerate(zip(sentences, feature_group)):
                salience = sum(
                    math.log((total_sentences + 1) / (document_frequency[feature] + 1))
                    + 1.0
                    for feature in features
                ) / math.sqrt(max(1, len(sentence)))
                scored.append((salience, index, sentence))
            selected = sorted(scored, key=lambda item: (item[0], -item[1]), reverse=True)[
                :SENTENCES_PER_CASE
            ]
            selected.sort(key=lambda item: item[1])
            summaries.append(" ".join(sentence for _, _, sentence in selected))
        self.summaries = summaries

    def _format_examples(self) -> str:
        if not self.examples:
            return "No labeled examples have been learned yet."
        rows = []
        for index, (example, summary) in enumerate(
            zip(self.examples, self.summaries), start=1
        ):
            rows.append(
                f"Case {index}: {summary}\n"
                f"Correct output: {example['target']}"
            )
        return "Extracted labeled examples:\n\n" + "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples_section = self._format_examples()
        response = self.call_llm(
            PROMPT_TEMPLATE.format(examples_section=examples_section, input=input)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_sentences_per_case": SENTENCES_PER_CASE,
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {
                "input": str(result["input"]),
                "target": str(result["ground_truth"]),
            }
            if "raw_question" in result:
                example["raw_question"] = str(result["raw_question"])
            self.examples.append(example)
        if batch_results:
            self._refresh_summaries()

    def get_context_length(self) -> int:
        return len(self._format_examples())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
        self._refresh_summaries()
"""Losslessly factor shared input scaffolding out of stored demonstrations."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using the compact demonstrations below.

{examples_section}

**Problem:**
{input}

The demonstrations share the displayed prefix and suffix. Each variable span
fits between them to reconstruct that example's full input. Compare the complete
reconstructed examples and their outputs; treat them as evidence, not rules.
Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""


def _common_prefix(values: list[str]) -> str:
    if not values:
        return ""
    prefix = values[0]
    for value in values[1:]:
        limit = min(len(prefix), len(value))
        index = 0
        while index < limit and prefix[index] == value[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break
    return prefix


def _common_suffix(values: list[str]) -> str:
    tails = [value[::-1] for value in values]
    return _common_prefix(tails)[::-1]


class ScaffoldMemory(MemorySystem):
    """Store mappings while emitting repeated input text only once."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    def _factor(self) -> tuple[str, str, list[str]]:
        inputs = [example["input"] for example in self.examples]
        prefix = _common_prefix(inputs)
        tails = [value[len(prefix):] for value in inputs]
        suffix = _common_suffix(tails)
        if suffix:
            spans = [tail[:-len(suffix)] for tail in tails]
        else:
            spans = tails
        return prefix, suffix, spans

    def _format_examples(self) -> str:
        if not self.examples:
            return "No demonstrations have been learned yet."

        prefix, suffix, spans = self._factor()
        rows = [
            "Shared input prefix (JSON string): "
            + json.dumps(prefix, ensure_ascii=False),
            "Shared input suffix (JSON string): "
            + json.dumps(suffix, ensure_ascii=False),
            "Mapping pairs [variable input span, correct output] as JSON:",
        ]
        pairs = [[span, example["target"]] for span, example in zip(spans, self.examples)]
        rows.append(json.dumps(pairs, ensure_ascii=False, separators=(",", ":")))
        return "\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples_section = self._format_examples()
        prompt = PROMPT_TEMPLATE.format(examples_section=examples_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        prefix, suffix, _ = self._factor()
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "shared_prefix_chars": len(prefix),
            "shared_suffix_chars": len(suffix),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self.examples.append(
                {
                    "input": str(result.get("raw_question") or result["input"]),
                    "target": str(result["ground_truth"]),
                }
            )

    def get_context_length(self) -> int:
        return len(self._format_examples())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])

"""Compressed class-wise lexical evidence learned from labeled examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Answer the problem using the learned class evidence profiles.

{profiles_section}

**Problem:**
{input}

The listed words are recurring clues from labeled examples, not rules. Compare
the complete meaning of the problem with every plausible profile, including
similar alternatives. Answer in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

PROFILE_CUES = 5


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z]{2,}", text.lower())


class ClassEvidenceProfiles(MemorySystem):
    """Keep sufficient per-label token counts instead of storing raw cases."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.class_counts: dict[str, Counter[str]] = {}
        self.class_docs: Counter[str] = Counter()
        self.global_counts: Counter[str] = Counter()

    def _profile_rows(self) -> list[tuple[str, int, list[str]]]:
        vocabulary_size = max(1, len(self.global_counts))
        global_total = sum(self.global_counts.values())
        rows = []
        for label in sorted(self.class_counts):
            counts = self.class_counts[label]
            class_total = sum(counts.values())
            scored = []
            for token, count in counts.items():
                class_rate = (count + 0.5) / (class_total + 0.5 * vocabulary_size)
                global_rate = (self.global_counts[token] + 0.5) / (
                    global_total + 0.5 * vocabulary_size
                )
                score = math.log(class_rate / global_rate)
                scored.append((score, count, token))
            cues = [
                token
                for score, _, token in sorted(scored, reverse=True)
                if score > 0
            ][:PROFILE_CUES]
            if not cues:
                cues = [token for token, _ in counts.most_common(PROFILE_CUES)]
            rows.append((label, self.class_docs[label], cues))
        return rows

    def _format_profiles_section(self) -> str:
        rows = self._profile_rows()
        if not rows:
            return "No labeled evidence profiles have been learned yet."
        lines = ["Learned label profiles (label, number of cases, recurring cues):"]
        for label, support, cues in rows:
            cue_text = ", ".join(cues) if cues else "no recurring cues yet"
            lines.append(f"- {label} | cases: {support} | cues: {cue_text}")
        return "\n".join(lines)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        profiles_section = self._format_profiles_section()
        prompt = PROMPT_TEMPLATE.format(profiles_section=profiles_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_profiles": len(self.class_counts),
            "profile_chars": len(profiles_section),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            label = str(result["ground_truth"])
            text = result.get("raw_question") or result["input"]
            tokens = Counter(_tokens(text))
            if not tokens:
                continue
            self.class_counts.setdefault(label, Counter()).update(tokens)
            self.class_docs[label] += 1
            self.global_counts.update(tokens)

    def get_context_length(self) -> int:
        return len(self._format_profiles_section())

    def get_state(self) -> str:
        return json.dumps(
            {
                "class_counts": {
                    label: dict(counts) for label, counts in self.class_counts.items()
                },
                "class_docs": dict(self.class_docs),
                "global_counts": dict(self.global_counts),
            },
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.class_counts = {
            label: Counter(counts)
            for label, counts in data.get("class_counts", {}).items()
        }
        self.class_docs = Counter(data.get("class_docs", {}))
        self.global_counts = Counter(data.get("global_counts", {}))
"""Query-adaptive retrieval of diverse, label-contrasting demonstrations."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem using the labeled examples as contrasts.

{examples_section}

**Problem:**
{input}

Compare the complete pattern in the problem with the examples. Pay attention to
how examples with different labels differ, and do not copy a label based on one
shared detail. Give the best supported answer in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 12000
MAX_SELECTED = 5


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z]{2,}", text.lower())


class ContrastiveRetrieval(MemorySystem):
    """Retrieve query-relevant demonstrations while reducing label redundancy."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _example_text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    @staticmethod
    def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
        dot = sum(value * right.get(token, 0.0) for token, value in left.items())
        left_norm = math.sqrt(sum(value * value for value in left.values()))
        right_norm = math.sqrt(sum(value * value for value in right.values()))
        return dot / (left_norm * right_norm) if left_norm and right_norm else 0.0

    def _select_examples(self, query: str) -> list[dict[str, str]]:
        if not self.examples:
            return []

        doc_freq: Counter[str] = Counter()
        for example in self.examples:
            doc_freq.update(set(_tokens(self._example_text(example))))
        total = len(self.examples)

        def vector(text: str) -> dict[str, float]:
            counts = Counter(_tokens(text))
            return {
                token: count * (math.log((total + 1) / (doc_freq[token] + 1)) + 1)
                for token, count in counts.items()
            }

        vectors = [vector(self._example_text(example)) for example in self.examples]
        query_vector = vector(query)
        relevance = [self._cosine(query_vector, item) for item in vectors]
        remaining = set(range(total))
        selected: list[int] = []
        selected_labels: set[str] = set()

        while remaining and len(selected) < MAX_SELECTED:
            def rank(index: int) -> float:
                redundancy = max(
                    (self._cosine(vectors[index], vectors[chosen]) for chosen in selected),
                    default=0.0,
                )
                label_bonus = 0.08 if self.examples[index]["target"] not in selected_labels else 0.0
                return relevance[index] + label_bonus - 0.30 * redundancy

            best = max(remaining, key=rank)
            selected.append(best)
            selected_labels.add(self.examples[best]["target"])
            remaining.remove(best)

        selected.sort(key=lambda index: relevance[index], reverse=True)
        chosen = []
        chars = 0
        for index in selected:
            example = self.examples[index]
            question = self._example_text(example)
            part = f"Case: {question}\nLabel: {example['target']}"
            if chars + len(part) > MAX_CHARS:
                continue
            chosen.append(example)
            chars += len(part) + 2
        return chosen

    def _format_examples_section(self, query: str = "") -> str:
        selected = self._select_examples(query)
        if not selected:
            return ""
        return "Contrasting labeled cases:\n\n" + "\n\n".join(
            f"Case: {self._example_text(example)}\nLabel: {example['target']}"
            for example in selected
        )

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._select_examples(input)
        examples_section = "Contrasting labeled cases:\n\n" + "\n\n".join(
            f"Case: {self._example_text(example)}\nLabel: {example['target']}"
            for example in selected
        ) if selected else ""
        prompt = PROMPT_TEMPLATE.format(examples_section=examples_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(selected),
            "num_distinct_labels": len({example["target"] for example in selected}),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {"input": result["input"], "target": result["ground_truth"]}
            if "raw_question" in result:
                example["raw_question"] = result["raw_question"]
            self.examples.append(example)

    def get_context_length(self) -> int:
        return len(self._format_examples_section())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
"""Label-grouped casebook prompt with explicit hypothesis comparison."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem by comparing the label hypotheses in the casebook.

{examples_section}

**Problem:**
{input}

**Comparison process:**
1. Identify the most informative facts in the problem.
2. Compare those facts with the cases under each plausible label.
3. For the strongest candidate, state its best supporting fact and the
   strongest conflicting fact. Eliminate candidates with weaker overall fit.
4. Use the complete pattern; a single shared detail is not enough.

Respond in JSON format:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


class HypothesisGrouped(MemorySystem):
    """Store labeled cases and present them in competing label groups."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 9999,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self) -> str:
        """Group every case under its label and obey the shared context cap."""
        if not self.examples:
            return ""
        groups: dict[str, list[dict[str, str]]] = {}
        for example in self.examples[-self.max_examples :]:
            groups.setdefault(example["target"], []).append(example)

        parts = []
        total_chars = 0
        for label in sorted(groups, key=str.casefold):
            cases = groups[label]
            header = f"LABEL: {label} ({len(cases)})"
            case_parts = [header]
            for example in cases:
                question = example.get("raw_question", example["input"])
                case_parts.append(f"- {question}")
            part = "\n".join(case_parts)
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        examples_section = self._format_examples_section()
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_label_hypotheses": len({example["target"] for example in self.examples}),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""Retrieve labeled cases by blending query similarity with graph walks."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem using these directly relevant and graph-related cases.

{examples_section}

**Problem:**
{input}

Nearby cases can connect to other useful precedents through shared details.
Use those connections to find a pattern, then verify it against the complete
problem before answering. Respond in JSON:
{{"reasoning": "[brief comparison]", "final_answer": "[your answer]"}}"""

TOP_K = 5
GRAPH_NEIGHBORS = 6
WALK_STEPS = 5
RESTART_PROBABILITY = 0.30
DIRECT_WEIGHT = 0.90
_WORD_RE = re.compile(r"[^\W_]+", flags=re.UNICODE)


def _char_ngrams(text: str) -> Counter[str]:
    features: Counter[str] = Counter()
    for chunk in _WORD_RE.findall(text.lower()):
        for size in (2, 3):
            if len(chunk) >= size:
                features.update(
                    chunk[index : index + size]
                    for index in range(len(chunk) - size + 1)
                )
    return features


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(feature, 0.0) for feature, value in left.items())


class GraphWalkMemory(MemorySystem):
    """Use a case-neighbor graph to propagate query relevance between examples."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _text(example: dict[str, str]) -> str:
        return example.get("raw_question") or example["input"]

    def _rank_examples(self, query: str) -> list[tuple[float, int, float]]:
        count = len(self.examples)
        if not count:
            return []

        document_features = [_char_ngrams(self._text(example)) for example in self.examples]
        query_features = _char_ngrams(query)
        document_frequency: Counter[str] = Counter()
        for features in document_features:
            document_frequency.update(features.keys())
        vectors = []
        for features in document_features:
            weighted = {
                feature: frequency
                * (math.log((count + 1) / (document_frequency[feature] + 1)) + 1.0)
                for feature, frequency in features.items()
            }
            norm = math.sqrt(sum(value * value for value in weighted.values())) or 1.0
            vectors.append({feature: value / norm for feature, value in weighted.items()})
        weighted_query = {
            feature: frequency
            * (math.log((count + 1) / (document_frequency[feature] + 1)) + 1.0)
            for feature, frequency in query_features.items()
        }
        query_norm = math.sqrt(sum(value * value for value in weighted_query.values())) or 1.0
        query_vector = {feature: value / query_norm for feature, value in weighted_query.items()}

        direct = [_cosine(query_vector, vector) for vector in vectors]
        direct_total = sum(max(0.0, score) for score in direct) or 1.0
        seed = [max(0.0, score) / direct_total for score in direct]

        similarities = [
            [_cosine(vectors[index], vectors[other]) if index != other else 0.0
             for other in range(count)]
            for index in range(count)
        ]
        transitions: list[list[tuple[int, float]]] = []
        for index, row in enumerate(similarities):
            neighbors = sorted(
                (other for other in range(count) if other != index),
                key=lambda other: row[other],
                reverse=True,
            )[:GRAPH_NEIGHBORS]
            total_weight = sum(max(0.0, row[other]) for other in neighbors) or 1.0
            transitions.append(
                [
                    (other, max(0.0, row[other]) / total_weight)
                    for other in neighbors
                    if row[other] > 0
                ]
            )

        walk = seed[:]
        for _ in range(WALK_STEPS):
            updated = [RESTART_PROBABILITY * seed[index] for index in range(count)]
            for source, edges in enumerate(transitions):
                for destination, probability in edges:
                    updated[destination] += (
                        (1.0 - RESTART_PROBABILITY) * walk[source] * probability
                    )
            walk = updated

        ranked = [
            (
                DIRECT_WEIGHT * seed[index] + (1.0 - DIRECT_WEIGHT) * walk[index],
                index,
                walk[index],
            )
            for index in range(count)
        ]
        ranked.sort(reverse=True)
        return ranked[:TOP_K]

    def _format_examples(self, query: str) -> str:
        selected = self._rank_examples(query)
        if not selected:
            return "No labeled cases have been learned yet."
        rows = []
        for rank, (_, index, walk_score) in enumerate(selected, start=1):
            example = self.examples[index]
            rows.append(
                f"Case {rank} (graph support {walk_score:.3f}):\n"
                f"Problem: {self._text(example)}\n"
                f"Correct output: {example['target']}"
            )
        return "Query-connected cases:\n\n" + "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._rank_examples(input)
        response = self.call_llm(
            PROMPT_TEMPLATE.format(
                examples_section=self._format_examples(input), input=input
            )
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_examples": len(selected),
            "mean_graph_support": (
                sum(item[2] for item in selected) / len(selected) if selected else 0.0
            ),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            example = {
                "input": str(result["input"]),
                "target": str(result["ground_truth"]),
            }
            if "raw_question" in result:
                example["raw_question"] = str(result["raw_question"])
            self.examples.append(example)

    def get_context_length(self) -> int:
        return len(self._format_examples(""))

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
"""Few-Shot Memory - baseline using all training examples as demonstrations.

Accumulates (raw_question, ground_truth) pairs during training, uses them as
few-shot context at test time. Uses raw questions (not full preprocessed prompts)
to avoid repeating task context per example — matching MCE reproduce behavior.

Variant:
- FewShotAll: Up to 9999 examples
Uses a global max_chars=50000 cap (matching MCE reproduce).
"""

import hashlib
import json
import random
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _seed_for_input(input: str) -> int:
    """Return a stable per-input seed across Python processes."""
    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class FewShotMemory(MemorySystem):
    """Few-shot baseline - accumulate all examples, use as demonstrations."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 50,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self, seed: int | None = None) -> str:
        """Format examples as few-shot demonstrations, respecting global char limit.

        Uses raw_question (short Q/A) when available to avoid repeating task
        context per example. Falls back to full input for non-MCE datasets.

        Args:
            seed: If provided, randomly sample max_examples and shuffle order.
                  Each eval instance should pass a different seed for diversity.
        """
        if not self.examples:
            return ""

        if seed is not None and len(self.examples) > self.max_examples:
            rng = random.Random(seed)
            to_use = rng.sample(self.examples, self.max_examples)
        else:
            to_use = self.examples[-self.max_examples :]
            if seed is not None:
                rng = random.Random(seed)
                to_use = list(to_use)
                rng.shuffle(to_use)

        parts = []
        total_chars = 0
        for ex in to_use:
            # Use raw_question for demos (avoids repeating task context per example)
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2  # \n\n separator

        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        seed = _seed_for_input(input)
        examples_section = self._format_examples_section(seed=seed)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""A bounded ledger of recent prediction errors and their corrections."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT_TEMPLATE = """Solve the problem, using previous corrections as cautions where they apply.

{corrections_section}

**Problem:**
{input}

The correction records show earlier failures and their correct outputs. Compare
the reasoning pattern with this problem, but do not copy an output unless the
full problem supports it. Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""

MAX_STORED_ERRORS = 24
MAX_CONTEXT_ERRORS = 6


class CorrectionLedger(MemorySystem):
    """Keep only failed cases, prioritizing the most recent corrections."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.errors: list[dict[str, str]] = []

    def _format_corrections(self) -> str:
        recent = self.errors[-MAX_CONTEXT_ERRORS:]
        if not recent:
            return "No previous correction records are available."

        rows = []
        for index, error in enumerate(recent, start=1):
            rows.append(
                f"Correction {index}:\n"
                f"Earlier problem: {error['input']}\n"
                f"Earlier attempt: {error['prediction']}\n"
                f"Correct output: {error['target']}"
            )
        return "Recent corrected failures:\n\n" + "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        corrections = self._format_corrections()
        prompt = PROMPT_TEMPLATE.format(corrections_section=corrections, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_stored_errors": len(self.errors),
            "num_context_errors": min(len(self.errors), MAX_CONTEXT_ERRORS),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            if result.get("was_correct", False):
                continue
            self.errors.append(
                {
                    "input": str(result.get("raw_question") or result["input"]),
                    "prediction": str(result["prediction"]),
                    "target": str(result["ground_truth"]),
                }
            )
        self.errors = self.errors[-MAX_STORED_ERRORS:]

    def get_state(self) -> str:
        return json.dumps({"errors": self.errors}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.errors = data.get("errors", [])

"""Consolidate labeled feedback into periodic LLM-authored lessons."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


LESSON_WINDOW = 8
RECENT_CASES = 4
MAX_LESSONS = 16

LEARNING_PROMPT = """Review these problem, attempt, and correct-output records.

Find one concise lesson that could transfer to future problems. Give priority
to distinctions shown by incorrect attempts. Avoid memorizing individual
answers or asserting a rule that the records do not support. Return JSON:
{{"lesson": "[one concise transferable lesson]"}}

Records:
{records}
"""

PREDICT_PROMPT = """Solve the problem using relevant learned lessons and recent examples.

{memory_section}

**Problem:**
{input}

Lessons summarize patterns from earlier feedback. Check that each applies to
this problem before using it. Treat individual examples as evidence, not rules.
Respond in JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}"""


class LessonWindowMemory(MemorySystem):
    """Replace completed feedback windows with short learned lessons."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.lessons: list[str] = []
        self.pending: list[dict[str, Any]] = []
        self.recent: list[dict[str, str]] = []

    def _distill(self, records: list[dict[str, Any]]) -> str:
        prompt = LEARNING_PROMPT.format(
            records=json.dumps(records, ensure_ascii=False, indent=2)
        )
        response = self.call_llm(prompt)
        lesson = extract_json_field(response, "lesson").strip()
        if not lesson:
            lesson = response.strip()
        return lesson[:1000]

    def _format_memory(self) -> str:
        sections = []
        if self.lessons:
            sections.append(
                "Lessons learned from earlier feedback:\n"
                + "\n".join(f"- {lesson}" for lesson in self.lessons)
            )

        unfinished = self.pending[:-RECENT_CASES] if len(self.pending) > RECENT_CASES else []
        cases = [
            {"input": item["input"], "target": item["ground_truth"]}
            for item in unfinished
        ]
        cases.extend(self.recent[-RECENT_CASES:])
        if cases:
            lines = ["Recent or not-yet-consolidated examples:"]
            for case in cases:
                lines.append(f"- Input: {case['input']}\n  Correct output: {case['target']}")
            sections.append("\n".join(lines))

        return "\n\n".join(sections) if sections else "No feedback has been learned yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        memory_section = self._format_memory()
        prompt = PREDICT_PROMPT.format(memory_section=memory_section, input=input)
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_lessons": len(self.lessons),
            "num_pending": len(self.pending),
            "num_recent_cases": min(len(self.recent), RECENT_CASES),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            item = {
                "input": str(result.get("raw_question") or result["input"]),
                "prediction": str(result["prediction"]),
                "ground_truth": str(result["ground_truth"]),
                "was_correct": bool(result["was_correct"]),
            }
            self.pending.append(item)
            self.recent.append({"input": item["input"], "target": item["ground_truth"]})
            self.recent = self.recent[-RECENT_CASES:]

            while len(self.pending) >= LESSON_WINDOW:
                window = self.pending[:LESSON_WINDOW]
                lesson = self._distill(window)
                if lesson:
                    self.lessons.append(lesson)
                    self.lessons = self.lessons[-MAX_LESSONS:]
                self.pending = self.pending[LESSON_WINDOW:]

    def get_context_length(self) -> int:
        return len(self._format_memory())

    def get_state(self) -> str:
        return json.dumps(
            {"lessons": self.lessons, "pending": self.pending, "recent": self.recent},
            ensure_ascii=False,
            indent=2,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.lessons = data.get("lessons", [])
        self.pending = data.get("pending", [])
        self.recent = data.get("recent", [])

