"""Maintain a compact, incrementally updated profile for each output label."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


LEARNING_PROMPT = """Update the compact profile for one correct output using a new labeled example.

Preserve recurring evidence and constraints already supported by the previous
profile. Add only information from the new example that could help distinguish
this output in a future problem. Do not infer unsupported rules or copy
incidental identifiers. Keep the profile to at most three short sentences.
Return JSON: {{"profile": "..."}}

Correct output: {label}
Previous profile: {previous}
New input: {input}
"""

PREDICT_PROMPT = """Answer the problem by comparing it with the learned output profiles.

{profiles_section}

Profiles summarize examples associated with each output. They are evidence,
not rules. Compare the complete input with plausible alternatives, and use the
required answer format from the problem. Return JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}

Problem:
{input}
"""


class LabelPrototypeMemory(MemorySystem):
    """Compress examples into a semantic prototype maintained per output."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.profiles: dict[str, dict[str, Any]] = {}

    def _update_profile(self, label: str, text: str) -> None:
        current = self.profiles.get(label, {"profile": "", "support": 0})
        prompt = LEARNING_PROMPT.format(
            label=label,
            previous=current["profile"] or "None yet",
            input=text,
        )
        response = self.call_llm(prompt)
        profile = extract_json_field(response, "profile").strip()
        if not profile:
            profile = text[:600]
        self.profiles[label] = {
            "profile": profile[:1200],
            "support": int(current["support"]) + 1,
        }

    def _format_profiles(self) -> str:
        if not self.profiles:
            return "No labeled output profiles have been learned yet."
        rows = ["Learned output profiles:"]
        for label in sorted(self.profiles, key=str.casefold):
            record = self.profiles[label]
            rows.append(
                f"- Output: {label} (examples: {record['support']})\n"
                f"  Profile: {record['profile']}"
            )
        return "\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        profiles_section = self._format_profiles()
        response = self.call_llm(
            PREDICT_PROMPT.format(profiles_section=profiles_section, input=input)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_profiles": len(self.profiles),
            "profile_chars": len(profiles_section),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            label = str(result["ground_truth"])
            text = str(result.get("raw_question") or result["input"])
            self._update_profile(label, text)

    def get_context_length(self) -> int:
        return len(self._format_profiles())

    def get_state(self) -> str:
        return json.dumps({"profiles": self.profiles}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.profiles = data.get("profiles", {})
"""Use a skeptical second pass to audit a few-shot draft against precedents."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


DRAFT_PROMPT = """Solve the problem using the labeled precedents.

{examples_section}

Problem:
{input}

Use the complete problem and follow its answer format. Return JSON with
reasoning and final_answer.
"""

AUDIT_PROMPT = """Audit this draft answer against the problem and labeled precedents.

Labeled precedents:
{examples_section}

Problem:
{input}

Draft answer: {draft_answer}
Draft reasoning: {draft_reasoning}

Act as a skeptical verifier. Identify the strongest precedent supporting the
draft and the strongest conflicting precedent. Check whether their relevant
facts actually match the full problem. Keep or revise the answer based on that
comparison. Follow the answer format requested in the problem. Return JSON
with reasoning and final_answer.
"""


def _seed_for_input(input: str) -> int:
    import hashlib

    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class CountercheckFewshot(MemorySystem):
    """Draft with all learned examples, then independently audit the draft."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    @staticmethod
    def _example_text(example: dict[str, str]) -> str:
        return example.get("raw_question", example["input"])

    def _format_examples(self, input: str) -> str:
        if not self.examples:
            return "No labeled precedents have been learned yet."
        # A stable rotation varies presentation across problems without changing coverage.
        start = _seed_for_input(input) % len(self.examples)
        ordered = self.examples[start:] + self.examples[:start]
        return "\n\n".join(
            f"Precedent:\nProblem: {self._example_text(example)}\n"
            f"Correct output: {example['target']}"
            for example in ordered
        )

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples_section = self._format_examples(input)
        draft_response = self.call_llm(
            DRAFT_PROMPT.format(examples_section=examples_section, input=input)
        )
        draft_answer = extract_json_field(draft_response, "final_answer")
        draft_reasoning = extract_json_field(draft_response, "reasoning")[:1000]

        audit_response = self.call_llm(
            AUDIT_PROMPT.format(
                examples_section=examples_section,
                input=input,
                draft_answer=draft_answer,
                draft_reasoning=draft_reasoning,
            )
        )
        answer = extract_json_field(audit_response, "final_answer") or draft_answer
        return answer, {
            "full_response": audit_response,
            "draft_response": draft_response,
            "draft_answer": draft_answer,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self.examples.append(
                {
                    "input": str(result["input"]),
                    "raw_question": str(result.get("raw_question") or result["input"]),
                    "target": str(result["ground_truth"]),
                }
            )

    def get_context_length(self) -> int:
        return len(self._format_examples(""))

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])
"""Replace each labeled example with an LLM-written semantic case card."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


CARD_PROMPT = """Compress this labeled example into one compact case card.

Capture the concrete evidence in the input that supports the correct output.
Preserve constraints or exceptions that could change the answer. Avoid
unsupported generalizations and incidental identifiers. Keep the card under
80 words. Return JSON: {{"case_card": "..."}}

Correct output: {target}
Input: {input}
"""

PREDICT_PROMPT = """Solve the problem using the labeled semantic case cards.

{cards_section}

Cards preserve decision-relevant evidence from earlier examples. Treat each
card as partial evidence, compare the full input, and follow the answer format
requested in the problem. Return JSON:
{{"reasoning": "[brief explanation]", "final_answer": "[your answer]"}}

Problem:
{input}
"""


class SemanticCaseCards(MemorySystem):
    """Store one concise semantic record for every labeled training case."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.cards: list[dict[str, str]] = []

    def _make_card(self, text: str, target: str) -> str:
        response = self.call_llm(CARD_PROMPT.format(target=target, input=text))
        card = extract_json_field(response, "case_card").strip()
        return (card or text[:800])[:1000]

    def _format_cards(self) -> str:
        if not self.cards:
            return "No labeled case cards have been learned yet."
        rows = ["Labeled semantic precedents:"]
        for index, item in enumerate(self.cards, start=1):
            rows.append(
                f"Case {index}: {item['card']}\n"
                f"Correct output: {item['target']}"
            )
        return "\n\n".join(rows)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        cards_section = self._format_cards()
        response = self.call_llm(
            PREDICT_PROMPT.format(cards_section=cards_section, input=input)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_cards": len(self.cards),
            "card_chars": len(cards_section),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            text = str(result.get("raw_question") or result["input"])
            target = str(result["ground_truth"])
            self.cards.append({"card": self._make_card(text, target), "target": target})

    def get_context_length(self) -> int:
        return len(self._format_cards())

    def get_state(self) -> str:
        return json.dumps({"cards": self.cards}, ensure_ascii=False, indent=2)

    def set_state(self, state: str) -> None:
        self.cards = json.loads(state).get("cards", [])
